    "Method 2: $73 = bq_1 + r$ $(1)$, $216 = bq_2 + r$ $(2)$, $227 = bq_3 + r$ $(3)$. $(3) - (2)$: $11 = b(q_3 - q_2)$. Since $11$ is a prime number, and $b$ is not $1$, so $b$ equals $11$. $108 = 11 \\times 9 + 9$. The remainder when $108$ is divided by $b$ is $9$."
