    "We see that from $(1)$ and $(3)$ that $x$ and $y$ are the roots of the quadratic equation: $t^2-2t+(1+z^2)=0$ $(4)$",
    "The discriminant $\\Delta=4-4(1+z^2)=-4z^2\\leq 0$",
    "Only when $z^2=0$ or $z=0$ does the equations have real roots.",
    "$(4)$ becomes $t^2-2t+1=0 \\Rightarrow (t-1)^2=0 \\Rightarrow t=1$.",
    "The solution of $(x,\\,y,\\,z)$ is $(1,\\,1,\\,0)$."
