   "q": "$ABCD$ is an isosceles trapezoid with $\\overline{AB}$ parallel to $\\overline{DC}$, $AC = DC$, and $AD = BC$. If the height $h$ of the trapezoid is equal to $AB$, find the ratio $AB : DC$.",
