    "$\\dfrac{V_S}{V_C} = \\dfrac{\\frac{4}{3}\\pi R^3}{\\pi r^2 h} = \\dfrac{4}{3} \\dfrac{k^3}{r^2 \\times \\frac{6}{5}k} = \\dfrac{10}{9}(\\dfrac{k}{r})^2$ (1)",
