   "q": "$ABCD$ is a trapezoid with bases $\\overline{AB}$ and $\\overline{CD}$. The measure of $\\angle A = 30^\\circ$, the measure $\\angle B = 60^\\circ$, $DC = 8$, and $AD = 12$. The perimeter of trapezoid $ABCD$ is:",
