   "q": "$ABCD$ is a trapezoid. Given $\\overline{AB} \\parallel \\overline{CD}$, $DC = 8$ m, $AC = 12$ m, $m\\angle A = m\\angle B = 45^\\circ$. The area of trapezoid $ABCD$ is:",
