   "id": "amc-circles-8",
   "q": "Line segment $\\overline{AB}$ has length $16$ inches and is tangent to the circle centered at $D$ whose diameter is $12$ inches. The point of tangency $C$ is the midpoint of $\\overline{AB}$ and $FE$ is parallel to $CD$. Find the length of $FB$.",
