    "Method 1:",
    "Since $C$ is the midpoint of $\\overline{AB}$, $BC = 16/2 = 8$. We also know that $CD = 6$. So triangle $BCD$ is a 6-8-10 right triangle. Then $BE = 10 - 6 = 4$.",
