    "So $AF = FC = \\dfrac{AC}{2} = 2\\sqrt{5}$ and $BF^2 + AF^2 = 5^2 \\Rightarrow BF = \\sqrt{25 - 20} = \\sqrt{5}$.",
    "We see that $\\triangle BDA \\sim \\triangle BAF$.",
