    "$(2m + k - 1) \\times k = 2 \\times 84 = 2^3 \\times 3 \\times 7$",
    "We know that $k < 2m + k - 1$ and that $k$ and $2m + k - 1$ have different parity, so we set the value for $k$ so that it is as close as possible to $2m + k - 1$: $k(2m + k - 1) = 8 \\times 21$.",
    "So $k = 8$.",
    "Note that $2m + k - 1 = 21$ and $m = 7$. $84 = 7 + 8 + 9 + 10 + 11 + 12 + 13 + 14$."
