    "As shown in the figures, the arc $AB$ is the circumference of the circle $C$. Let the length of arc $AB$ be $x$. Then $\\dfrac{360°}{2\\pi \\times 3} = \\dfrac{40°}{x} \\Rightarrow \\dfrac{3}{2\\pi} = \\dfrac{1}{x} \\Rightarrow x = \\dfrac{2\\pi}{3}$.",
    "Then $2\\pi r = \\dfrac{2\\pi}{3} \\Rightarrow r = \\dfrac{1}{3}$.",
    "Applying Pythagorean Theorem to right triangle $OCD$: $h^2 = 3^2 - (\\dfrac{1}{3})^2 = \\dfrac{80}{9} \\Rightarrow h = \\sqrt{\\dfrac{80}{9}} = \\dfrac{4\\sqrt{5}}{3}$.",
    "$V = \\dfrac{1}{3}\\pi \\times (\\dfrac{1}{3})^2 \\times \\dfrac{4\\sqrt{5}}{3} = \\dfrac{4\\sqrt{5}}{81}\\pi$."
