   "steps": [
    "Multiples of $6$: $\\left\\lfloor 1000/6 \\right\\rfloor = 166$. Those also divisible by $9$ are multiples of $\\operatorname{lcm}(6,9)=18$: $\\left\\lfloor 1000/18 \\right\\rfloor = 55$. So $166 - 55 = 111$."
   ],
