   "q": "For positive numbers $x$ and $y$ the operation $\\spadesuit(x, y)$ is defined as $\\spadesuit(x, y) = x - \\dfrac{1}{y}$. What is $\\spadesuit(2, \\spadesuit(2, 2))$?",
