  {
   "id": "amc-polynomials-7",
   "q": "Mary divides a circle into $12$ sectors. The central angles of these sectors, measured in degrees, are all integers and they form an arithmetic sequence. What is the degree measure of the smallest possible sector angle?",
   "choices": [
    "$5$",
    "$6$",
    "$8$",
    "$10$",
    "$12$"
   ],
   "answer": 2,
   "steps": [
    "Let $a$ be the initial term and $d$ the common difference. The sum of the central angles is $a + (a+d) + \\cdots + (a+11d) = 12a + 66d = 360$, so $2a + 11d = 60$. Letting $d = 4$ yields the smallest possible positive integer value for $a$, namely $a = 8$."
   ],
   "level": 2,
   "src": "AMC 10A 2012 #10"
  },
  {
   "id": "amc-polynomials-8",
   "q": "A triangular array of 2016 coins has 1 coin in the first row, 2 coins in the second row, 3 coins in the third row, and so on up to $N$ coins in the $N$th row. What is the sum of the digits of $N$?",
   "choices": [
    "$4$",
    "$7$",
    "$8$",
    "$9$",
    "$10$"
   ],
   "answer": 3,
   "steps": [
    "There are $\\dfrac{N(N+1)}{2}$ coins in the array. Therefore $\\dfrac{N(N+1)}{2} = 2016$, so $N(N+1) = 4032$. Because $N(N+1) \\approx N^2$, we get $N \\approx \\sqrt{4032} \\approx 64$. Indeed, $63 \\cdot 64 = 4032$, so $N = 63$ and the sum of the digits of $N$ is $9$."
   ],
   "level": 2,
   "src": "AMC 10A 2016 #9"
  }
