   "id": "amc-quadgraphs-8",
   "q": "The real numbers $c$, $b$, $a$ form an arithmetic sequence with $a \\ge b \\ge c \\ge 0$. The quadratic $ax^2 + bx + c$ has exactly one root. What is this root?",
   "choices": [
    "$-7 - 4\\sqrt{3}$",
    "$-2 - \\sqrt{3}$",
    "$-1$",
    "$-2 + \\sqrt{3}$",
    "$-7 + 4\\sqrt{3}$"
   ],
   "answer": 3,
   "steps": [
    "Let the common difference be $d$, so $a = b + d$ and $c = b - d$. Exactly one root means $b^2 - 4ac = 0$, i.e. $b^2 = 4(b + d)(b - d)$, giving $3b^2 = 4d^2$ and $\\sqrt{3}\\,b = 2d$. The double root is $\\frac{-b}{2a} = \\frac{-b}{2(b + d)} = \\frac{-b}{2\\left(b + \\frac{\\sqrt{3}}{2}b\\right)} = -2 + \\sqrt{3}$."
   ],
