   "id": "amc-radicals-2",
   "q": "For how many (not necessarily positive) integer values of $n$ is the value of $4000 \\cdot \\left(\\dfrac{2}{5}\\right)^n$ an integer?",
   "choices": [
    "$3$",
    "$4$",
    "$6$",
    "$8$",
    "$9$"
   ],
   "answer": 4,
   "steps": [
    "Since $4000 = 2^5 \\cdot 5^3$, we have $4000 \\cdot \\left(\\frac{2}{5}\\right)^n = 2^{5+n} \\cdot 5^{3-n}$. This is an integer if and only if both $5+n \\geq 0$ and $3-n \\geq 0$, i.e., $-5 \\leq n \\leq 3$. There are $3 - (-5) + 1 = 9$ such integers."
   ],
