  {
   "id": "amc-circleangles-6",
   "q": "A triangle with side lengths in the ratio $3{:}4{:}5$ is inscribed in a circle of radius $3$. What is the area of the triangle?",
   "choices": [
    "$8.64$",
    "$12$",
    "$5\\pi$",
    "$17.28$",
    "$18$"
   ],
   "answer": 0,
   "steps": [
    "A $3{:}4{:}5$ triangle is right, so its hypotenuse is a diameter: $5x=6$, $x=\\frac{6}{5}$. The area is $\\frac{1}{2}(3x)(4x)=6x^2=6\\cdot\\frac{36}{25}=8.64$."
   ],
   "level": 3,
   "src": "AMC 10A 2007 #14"
  },
  {
   "id": "amc-circleangles-7",
   "q": "A circle passes through the three vertices of an isosceles triangle that has two sides of length $3$ and a base of length $2$. What is the area of this circle?",
   "choices": [
    "$2\\pi$",
    "$\\frac{5}{2}\\pi$",
    "$\\frac{81}{32}\\pi$",
    "$3\\pi$",
    "$\\frac{7}{2}\\pi$"
   ],
   "answer": 2,
   "steps": [
    "Let $BD$ be the altitude to the base; then $BD=\\sqrt{3^2-1^2}=2\\sqrt{2}$. With center $O$ on $BD$ and radius $r$, the right triangle $ADO$ gives $r^2=1^2+(2\\sqrt{2}-r)^2$, so $r=\\frac{9}{4\\sqrt{2}}=\\frac{9}{8}\\sqrt{2}$. The area is $\\pi r^2=\\frac{81}{32}\\pi$."
   ],
   "level": 3,
   "src": "AMC 10B 2007 #11"
  },
  {
   "id": "amc-circleangles-8",
   "q": "Isosceles triangle $ABC$ has $AB = AC = 3\\sqrt{6}$, and a circle with radius $5\\sqrt{2}$ is tangent to line $AB$ at $B$ and to line $AC$ at $C$. What is the area of the circle that passes through vertices $A$, $B$, and $C$?",
   "choices": [
    "$24\\pi$",
    "$25\\pi$",
    "$26\\pi$",
    "$27\\pi$",
    "$28\\pi$"
   ],
   "answer": 2,
   "steps": [
    "Let $O$ be the center of the circle with radius $5\\sqrt{2}$. Consider the circle with diameter $AO$. Because $\\angle ABO$ and $\\angle ACO$ are right angles, the opposite angles of quadrilateral $ABOC$ are supplementary, so $ABOC$ is cyclic. Thus $O$ is also on the circle through $A$, $B$, and $C$, and by symmetry $AO$ is a diameter. By the Pythagorean Theorem,\n$$AO=\\sqrt{\\left(5\\sqrt{2}\\right)^2+\\left(3\\sqrt{6}\\right)^2},$$\nso\n$$AO=\\sqrt{50+54}=\\sqrt{104}=2\\sqrt{26}.$$ \nTherefore the circumcircle has radius $\\sqrt{26}$, and its area is $26\\pi$."
   ],
   "level": 3,
   "src": "AMC 10Fall 2021 #15"
  }
