   "id": "amc-geoproof-2",
   "q": "A $3$-$4$-$5$ right triangle is inscribed in circle $A$, and a $5$-$12$-$13$ right triangle is inscribed in circle $B$. What is the ratio of the area of circle $A$ to the area of circle $B$?",
