  {
   "id": "amc-logarithms-6",
   "q": "There is a unique positive integer $n$ such that\n\n$$\\log_2(\\log_{16} n) = \\log_4(\\log_4 n).$$\n\nWhat is the sum of the digits of $n$?",
   "choices": [
    "$4$",
    "$7$",
    "$8$",
    "$11$",
    "$13$"
   ],
   "answer": 4,
   "steps": [
    "From the identity $\\log_a b = \\frac{\\log_c b}{\\log_c a}$ we deduce that $\\log_2 x = 2\\log_4 x$.\n\n(In general, $\\log_{a^b} c = \\frac{1}{b} \\log_a c$.)\n\nThen\n\n$$2\\log_4(\\log_{16} n) = \\log_4(\\log_4 n)$$\n\n$$\\Rightarrow (\\log_{16} n)^2 = \\log_4 n$$\n\nSince $\\log_{16} n = \\frac{\\log_4 n}{2}$, we have\n\n$$\\frac{(\\log_4 n)^2}{4} = \\log_4 n$$\n\n$$\\Rightarrow \\log_4 n = 4$$\n\n$$\\Rightarrow n = 4^4 = 256$$\n\n$$2 + 5 + 6 = 13 \\quad (E)$$"
   ],
   "level": 2,
   "src": "AMC12A 2020 #10"
  },
  {
   "id": "amc-logarithms-7",
   "q": "Positive real numbers $a$ and $b$ have the property that\n\n$$\\sqrt{\\log a} + \\sqrt{\\log b} + \\log \\sqrt{a} + \\log \\sqrt{b} = 100$$\n\nand all four terms on the left are positive integers, where $\\log$ denotes the base $10$ logarithm. What is $ab$?",
   "choices": [
    "$10^{52}$",
    "$10^{100}$",
    "$10^{144}$",
    "$10^{164}$",
    "$10^{200}$"
   ],
   "answer": 3,
   "steps": [
    "Let $\\log a = e^2$ and $\\log b = f^2$ for positive integers $e, f$. Then $\\sqrt{\\log a} = e$, $\\log\\sqrt{a} = e^2/2$, etc.\n\nThe equation becomes $e + f + \\frac{e^2}{2} + \\frac{f^2}{2} = 100$, i.e.,\n\n$$e^2 + f^2 + 2e + 2f = 200$$\n\n$$(e+1)^2 + (f+1)^2 = 202$$\n\nLooking for integer solutions: $e+1 = 9, f+1 = 11$ (or vice versa) since $81 + 121 = 202$. Wait, that's $202$. $9^2 + 11^2 = 81+121 = 202$. ✓\n\nSo $e = 8, f = 10$ (or vice versa, giving $e = 4, f = 5$... let me recheck).\n\nActually $\\sqrt{\\log a} = e$ means $\\log a = e^2$, and $\\log\\sqrt{a} = \\frac{e^2}{2}$ must be an integer, so $e$ is even. Similarly $f$ is even.\n\nWith $e = 4, f = 10$ (but $f$ must be even). Try $e = 4, f = 4$: $(5)^2 + (5)^2 = 50 \\ne 202$.\n\nThe valid solution is $e = 8, f = 10$: both even. ✓\n\n$\\log(ab) = e^2 + f^2 = 64 + 100 = 164$.\n\n$ab = 10^{164}$ (D)."
   ],
   "level": 3,
   "src": "AMC12A 2019 #15"
  },
  {
   "id": "amc-logarithms-8",
   "q": "What is the value of $(625^{\\log_5 2015})^{\\frac{1}{4}}$ ?",
   "choices": [
    "$5$",
    "$\\sqrt[4]{2015}$",
    "$625$",
    "$2015$",
    "$\\sqrt[4]{5^{2015}}$"
   ],
   "answer": 3,
   "steps": [
    "$(625^{\\log_5 2015})^\\frac{1}{4}=((5^4)^{\\log_5 2015})^\\frac{1}{4}=(5^{4 \\cdot \\log_5 2015})^\\frac{1}{4}=(5^{\\log_5 2015 \\cdot 4})^\\frac{1}{4}=((5^{\\log_5 2015})^4)^\\frac{1}{4}=(2015^4)^\\frac{1}{4}=\\boxed{\\textbf{(D)}\\; 2015}$"
   ],
   "level": 2,
   "src": "AMC12B 2015 #8"
  },
  {
   "id": "amc-logarithms-9",
   "q": "Positive real numbers $x \\ne 1$ and $y \\ne 1$ satisfy $\\log_2 x = \\log_y 16$ and $xy = 64$. What is $(\\log_2 \\frac{x}{y})^2$?",
   "choices": [
    "$\\frac{25}{2}$",
    "$20$",
    "$\\frac{45}{2}$",
    "$25$",
    "$32$"
   ],
   "answer": 1,
   "steps": [
    "From $xy = 64$: $\\log_2 x + \\log_2 y = 6$.\n\nFrom $\\log_2 x = \\log_y 16 = \\frac{4}{\\log_2 y}$:\n\n$$\\log_2 x \\cdot \\log_2 y = 4$$\n\nWe use $(A - B)^2 = (A+B)^2 - 4AB$:\n\n$$(\\log_2 x - \\log_2 y)^2 = 6^2 - 4 \\cdot 4 = 20$$\n\nSo $(\\log_2 \\frac{x}{y})^2 = 20$ (B)."
   ],
   "level": 3,
   "src": "AMC12A 2019 #12"
  }
