   "id": "amc-expmodels-2",
   "q": "Trickster Rabbit agrees with Foolish Fox to double Fox's money every time Fox crosses the bridge by Rabbit's house, as long as Fox pays $40$ coins in toll to Rabbit after each crossing. The payment is made after the doubling. Fox is excited about his good fortune until he discovers that all his money is gone after crossing the bridge three times. How many coins did Fox have at the beginning?",
   "choices": [
    "$20$",
    "$30$",
    "$35$",
    "$40$",
    "$45$"
   ],
   "answer": 2,
   "steps": [
    "Working backwards, Fox must have had $20$ coins before paying the toll the third time (since $20 - 40$ would leave him with nothing after doubling gave him $20 + 20 = 40$... actually, let's be precise). Let $c$ be the number of coins Fox had at the beginning. After three crossings he had $2(2(2c - 40) - 40) - 40 = 8c - 280$ coins. Setting this equal to $0$ gives $c = 35$."
   ],
