   "q": "Which one of the following rigid transformations (isometries) maps the line segment $\\overline{AB}$ onto the line segment $\\overline{A'B'}$ so that the image of $A(-2, 1)$ is $A'(2, -1)$ and the image of $B(-1, 4)$ is $B'(1, -4)$?",
