   "id": "amc-inequal6-1",
   "q": "Pablo buys popsicles for his friends. The store sells single popsicles for $\\$1$ each, $3$-popsicle boxes for $\\$2$, and $5$-popsicle boxes for $\\$3$. What is the greatest number of popsicles that Pablo can buy with $\\$8$?",
