   "q": "In a survey, $95$ television viewers offered their opinions about program $A$ and program $B$. Of those viewers, $28$ liked neither program $A$ nor program $B$, while $20$ liked both program $A$ and program $B$. If $25$ viewers liked program $A$ only, how many viewers liked program $B$ only?",
