   "id": "amc-statquestions-4",
   "q": "Of 100 citizens surveyed in a certain town, only $45\\%$ were in favor of the city council's proposition. $40\\%$ were opposed and $15\\%$ undecided. If the survey holds and 40,000 citizens vote, what percent of the undecided voters must vote in favor of the proposition in order for it to pass with $51\\%$ of the votes?",
   "choices": [
    "$25\\%$",
    "$35\\%$",
    "$40\\%$",
    "$45\\%$",
    "$50\\%$"
   ],
   "answer": 2,
   "steps": [
    "$51\\%$ of the votes are $51\\% \\times 40000 = 20400$ votes.",
    "$45\\%$ in favor means there are $45\\% \\times 40000 = 18000$ votes already.",
    "The number of votes needed is $20400 - 18000 = 2400$.",
    "$15\\%$ undecided means there are $15\\% \\times 40000 = 6000$ people undecided.",
    "The ratio is $2400 \\div 6000 = 0.4 = 40\\%$."
   ],
   "level": 2,
